30	<style>
31	:root {
32	  --p-bg: #f7f9fa; --p-surface: #ecf0f2; --p-ink: #1f3038; --p-muted: #5d6b72;
33	  --p-accent: #0d7480; --p-accent-ink: #ffffff; --p-action: #0d7480; --p-action-ink: #ffffff;
34	  --p-inv-bg: #1f3038; --p-inv-surface: #2c3c44; --p-inv-ink: #f7f9fa; --p-inv-muted: #9ea7ab;
35	  --p-inv-accent: #f7f9fa; --p-inv-accent-ink: #1f3038; --p-inv-action: #f7f9fa; --p-inv-action-ink: #1f3038;
36	  --font-display: "Instrument Sans", system-ui, sans-serif;
37	  --font-text: "Instrument Sans", system-ui, sans-serif;
38	  --font-mono: "DM Mono", ui-monospace, "SFMono-Regular", Menlo, Consolas, monospace;
39	  --display-weight: 500;
40	  --display-tracking: -0.028em;
41	  --display-tracking-xl: -0.036em;
42	  --display-stretch: 96%;
43	  --ly-scale: 1.04;
44	}
