54	<!-- page CSS: only what sits inside a visual (PitchSwitch's own screens, drawn as live HTML) -->
55	<style>
56	/* one window look for every PitchSwitch screen on the page: the app's chrome, its rows and its badges */
57	.pw { background: #fff; color: var(--p-ink); border: 1px solid rgb(31 48 56 / .12); border-radius: 14px; box-shadow: 0 24px 48px -28px rgb(31 48 56 / .45); font: 400 14px/1.45 var(--font-text); overflow: hidden; text-align: left; }
58	.pw__bar { display: flex; align-items: center; gap: 10px; height: 40px; padding: 0 14px; border-bottom: 1px solid rgb(31 48 56 / .09); font-size: 13px; color: var(--p-muted); white-space: nowrap; }
59	.pw__bar b { color: var(--p-ink); font-weight: 500; }
60	.pw__bar .sp { flex: 1; }
61	.pw__dots { display: flex; gap: 6px; } .pw__dots i { width: 9px; height: 9px; border-radius: 50%; background: rgb(31 48 56 / .14); }
62	.pw__tag { display: inline-flex; align-items: center; height: 22px; padding: 0 8px; border-radius: 6px; background: var(--p-ink); color: #fff; font: 500 12px/1 var(--font-text); flex: none; }
63	.pw__tag--pitch { background: var(--p-accent); }
64	.pw__src { display: inline-flex; gap: 6px; align-items: center; height: 22px; padding: 0 7px; border: 1px solid rgb(31 48 56 / .16); border-radius: 6px; font: 400 12px/1 var(--font-mono); color: var(--p-muted); white-space: nowrap; }
65	.pw__src em { font-style: normal; font-family: var(--font-text); font-weight: 500; color: var(--p-ink); }
66	.pw__chip { display: inline-flex; align-items: center; gap: 6px; height: 28px; padding: 0 10px; border: 1px solid var(--p-ink); border-radius: 7px; font-weight: 500; font-size: 13px; background: #fff; }
67	.pw__chip s { text-decoration: none; color: var(--p-muted); }
68	.pw__chips { display: flex; flex-wrap: wrap; gap: 6px; }
69	.pw__label { font: 500 12px/1.2 var(--font-text); color: var(--p-muted); }
70	
71	/* hero: the founder report, its Skip rows arriving one by one (layout.js data-ly-steps) */
72	.hero__window { background:
73	  radial-gradient(70% 90% at 15% 110%, #0d7480 0 30%, transparent 62%),
74	  radial-gradient(60% 80% at 90% 0%, #9fc7cc 0 25%, transparent 60%),
75	  linear-gradient(160deg, #cfe2e4, #e6eef0 55%, #b9d3d6); }
76	.pw--hero .pw__body { display: grid; grid-template-columns: 250px 1fr; min-height: 420px; }
77	.pw--hero .pw__side { padding: 16px; border-right: 1px solid rgb(31 48 56 / .09); display: grid; align-content: start; gap: 10px; }
78	.pw--hero .pw__main { padding: 16px 18px; display: grid; align-content: start; gap: 8px; }
79	.pw__verdict { margin: 0 0 4px; font: 500 18px/1.3 var(--font-display); letter-spacing: -0.01em; }
80	.pw__verdict u { text-decoration-color: var(--p-accent); text-decoration-thickness: 3px; text-underline-offset: 4px; }
81	.pw__row { display: grid; grid-template-columns: auto minmax(0, 1fr) auto; gap: 4px 10px; align-items: center; padding: 9px 10px; border-radius: 9px; background: var(--p-surface); }
82	.pw__row b { font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
83	.pw__row span:not([class]) { grid-column: 2; color: var(--p-muted); font-size: 13px; }
84	.pw__row .pw__src, .pw__row .pw__score { grid-column: 3; grid-row: 1 / span 2; }
85	.pw__score { font: 500 22px/1 var(--font-display); color: var(--p-accent); }
86	@media (max-width: 639px) {
87	  .pw--hero .pw__body { grid-template-columns: 1fr; min-height: 0; }
88	  .pw--hero .pw__side, .pw--hero .pw__bar .sp ~ span { display: none; }
89	  .pw__row .pw__src { display: none; }
90	}
91	
92	/* the report window (app-frame): the investor list beside the open Skip card */
93	.app.ui { display: grid; grid-template-columns: minmax(0, 5fr) minmax(0, 7fr); margin-top: var(--s-7); background: var(--u-bg); border: 1px solid var(--u-border); border-radius: var(--u-r); box-shadow: var(--u-shadow); }
94	.app > .app__pane { position: relative; min-width: 0; min-height: 0; overflow: hidden; }
95	.app > .app__pane + .app__pane { border-left: 1px solid var(--u-line); }
96	.app > .app__pane::after { content: ""; position: absolute; inset: auto 0 0 0; height: 64px; background: linear-gradient(transparent, var(--u-bg)); pointer-events: none; }
97	.inv__head { display: flex; align-items: center; gap: 12px; height: 48px; padding: 0 16px; border-bottom: 1px solid var(--u-line); font-size: 14px; }
98	.inv__head b { font-weight: 500; }
99	.inv__tabs { display: flex; gap: 4px; margin-left: auto; font-size: 13px; }
100	.inv__tabs span { padding: 4px 10px; border-radius: 99px; color: var(--p-muted); }
101	.inv__tabs span.is-on { background: var(--p-ink); color: #fff; }
102	.inv__list { list-style: none; margin: 0; padding: 6px; display: grid; gap: 2px; }
103	.inv__list li { display: grid; grid-template-columns: minmax(0, 1fr) auto; gap: 1px 12px; padding: 9px 12px; border-radius: 9px; font-size: 14px; }
104	.inv__list li.is-on { background: var(--p-surface); }
105	.inv__list b { font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
106	.inv__list small { grid-column: 1; color: var(--p-muted); font-size: 13px; }
107	.inv__list em { grid-column: 2; grid-row: 1 / span 2; align-self: center; font-style: normal; font: 500 13px/1 var(--font-text); }
108	.inv__list em.k { color: #fff; background: var(--p-ink); padding: 4px 8px; border-radius: 6px; }
109	.inv__list em.p { color: var(--p-accent); font-size: 18px; font-family: var(--font-display); }
110	.open { padding: 22px 26px; display: grid; gap: 14px; align-content: start; }
111	.open h3 { margin: 0; font: 500 26px/1.15 var(--font-display); letter-spacing: -0.02em; }
112	.open h3 small { margin-left: 8px; font: 500 12px/1 var(--font-text); color: var(--p-muted); }
113	.open__conflict { border-left: 4px solid var(--p-ink); padding-left: 14px; display: grid; gap: 8px; }
114	.open__conflict p { margin: 0; font-size: 18px; font-weight: 500; display: flex; gap: 10px; align-items: center; flex-wrap: wrap; }
115	.open__srcs { display: flex; gap: 6px; flex-wrap: wrap; }
116	.open__srcs .pw__src { max-width: 100%; overflow: hidden; text-overflow: ellipsis; }
117	.open__links { display: flex; gap: 18px; font-size: 14px; } .open__links span { text-decoration: underline; text-underline-offset: 4px; }
118	.open__rows { display: grid; gap: 0; border-top: 1px solid var(--u-line); }
119	.open__rows div { display: grid; grid-template-columns: 150px minmax(0, 1fr); gap: 12px; padding: 10px 0; border-bottom: 1px solid var(--u-line); font-size: 14px; }
120	.open__rows dt, .open__rows .k { color: var(--p-muted); }
121	@media (min-width: 1024px) and (max-width: 1279px) { .app.ui { grid-template-columns: minmax(0, 4fr) minmax(0, 8fr); } }
122	@media (max-width: 1023px) {
123	  .app.ui { grid-template-columns: minmax(0, 1fr); grid-template-rows: auto minmax(0, 1fr); }
124	  .app > .app__pane--list { max-height: 252px; }
125	  .app > .app__pane--list::after { display: none; }
126	  .app > .app__pane + .app__pane { border-left: 0; border-top: 1px solid var(--u-line); }
127	}
128	@media (max-width: 639px) {
129	  .app.ui { grid-template-rows: minmax(0, 1fr); }
130	  .app > .app__pane--list { display: none; }
131	  .app > .app__pane + .app__pane { border-top: 0; }
132	  .open { padding: 18px; } .open__rows div { grid-template-columns: 1fr; gap: 2px; }
133	}
134	
135	/* the dealt arc mark set inline in the hero's headline, as the centred hero sets its mark */
136	.hero--centred h1 .mark { width: .78em; height: .78em; vertical-align: -.04em; margin-inline-end: .08em; }
137	
138	/* the statement: one line set as large as the hero's, the liquid-type moment on it */
139	#statement h2 { font-size: clamp(48px, 9.4vw, 140px); line-height: .96; letter-spacing: var(--display-tracking-xl); max-width: 12ch; }
140	#statement .facts { display: flex; flex-wrap: wrap; gap: var(--s-4) var(--s-8); margin-top: var(--s-8); padding-top: var(--s-5); border-top: 1px solid rgb(31 48 56 / .14); }
141	#statement .facts div { display: grid; gap: 4px; } #statement .facts dt { font-size: 14px; color: var(--muted); } #statement .facts dd { margin: 0; font-size: 20px; font-weight: 500; }
142	
143	/* the investor check in the flip frame */
144	#flip .stage > .at-corner { --ax: 56px; --ay: 56px; }
145	.pw--check { width: 640px; }
146	.chk { padding: 18px 20px; display: grid; gap: 14px; }
147	.chk__as { font-size: 14px; color: var(--p-muted); } .chk__as b { color: var(--p-ink); font-weight: 500; border-bottom: 2px solid var(--p-accent); }
148	.chk__verdict { background: var(--p-ink); color: #fff; border-radius: 10px; padding: 16px 18px; display: grid; gap: 6px; }
149	.chk__verdict strong { font: 500 34px/1 var(--font-display); letter-spacing: -0.02em; }
150	.chk__verdict p { margin: 0; font-size: 15px; color: #dfe6e8; }
151	.chk__co { display: grid; gap: 8px; padding-top: 4px; }
152	.chk__co h4 { margin: 0; font: 500 18px/1.2 var(--font-display); }
153	.pw__chip--you { background: #d7ecee; border-color: var(--p-accent); }
154	.chk__round { display: flex; gap: 12px; align-items: baseline; font-size: 14px; padding: 10px 0; border-top: 1px solid rgb(31 48 56 / .09); }
155	.chk__round b { font-weight: 500; } .chk__round span { color: var(--p-muted); }
156	@media (max-width: 639px) { .pw--check { width: 100%; } }
157	
158	/* the tablet stacks the three steps: two screens there (layout-v4.md, the tablet) */
159	@media (min-width: 640px) and (max-width: 1023px) { #how { --h: 2; } }
160	
161	/* the three steps and the two cards: one panel height for each group */
162	#how .panel { --p-h: 280px; }
163	#slush .panel { --p-h: 300px; }
164	.mini { background: #fff; border: 1px solid rgb(31 48 56 / .12); border-radius: 12px; padding: 14px 16px; box-shadow: 0 16px 32px -24px rgb(31 48 56 / .5); font: 400 14px/1.45 var(--font-text); color: var(--p-ink); text-align: left; }
165	.mini__head { font: 500 12px/1.2 var(--font-text); color: var(--p-muted); margin: 0 0 10px; }
166	.bars { display: grid; gap: 7px; }
167	.bars div { display: grid; grid-template-columns: 112px 1fr 52px; gap: 10px; align-items: center; font-size: 13px; }
168	.bars i { display: block; height: 6px; border-radius: 3px; background: var(--p-surface); position: relative; }
169	.bars i::after { content: ""; position: absolute; inset: 0 auto 0 0; width: var(--w); border-radius: 3px; background: var(--p-accent); }
170	.bars b { font-weight: 500; text-align: right; font-variant-numeric: tabular-nums; }
171	.mono { font: 400 13px/1.6 var(--font-mono); background: var(--p-ink); color: #e6eef0; border-radius: 12px; padding: 16px 18px; text-align: left; white-space: pre-wrap; }
172	.mono sup { font-size: 10px; margin-left: 3px; padding: 0 4px; border-radius: 3px; background: #2c5a62; }
173	.mono .q { color: #fff; } .mono .t { color: #8fc3c9; } .mono .a { color: #fff; }
174	.brief p { margin: 0 0 8px; font-size: 15px; } .brief sup { font-size: 10px; background: #d7ecee; padding: 0 4px; border-radius: 3px; margin-left: 2px; }
175	.brief__ready { float: right; font: 500 12px/1 var(--font-text); background: var(--p-accent); color: #fff; padding: 5px 8px; border-radius: 6px; }
176	@media (max-width: 639px) { #how .panel, #slush .panel { --p-h: 220px; } .bars div { grid-template-columns: 96px 1fr 44px; } }
177	</style>
178	</head>
