191	      <div class="nav__item">
192	        <a class="nav__link" href="#report">Report <svg class="chev" viewBox="0 0 12 12" aria-hidden="true"><path d="M3 4.5l3 3 3-3" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg></a>
193	        <div class="nav__menu">
194	          <div class="wrap grid">
195	            <div class="menu-col span-3">
196	              <p class="t-label">Founder report</p>
